create table private.ovd591_retention_inputs(name text primary key,kind text not null,input jsonb not null);
revoke all on private.ovd591_retention_inputs from public,anon,authenticated,service_role;
create function private.ovd591_retention_claim(n integer,window_n integer default null) returns jsonb language sql as $$
 select jsonb_build_object('request',jsonb_build_object(
 'windowKey','canary:'||lpad(coalesce(window_n,n)::text,64,'0'),'resourceKey',lpad(n::text,64,'0'),
 'configDigest',repeat('a',64),'requestKey','00000000-0000-4000-8000-'||lpad(n::text,12,'0'),
 'provider','xometry','route','quote_home','surface','account_quote_modal','surfaceRevision','ovd591.retention',
 'windowStart',to_char(clock_timestamp()-interval '1 minute','YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'),
 'windowEnd',to_char(clock_timestamp()+interval '1 hour','YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'),'leaseSeconds',300),
 'completionKey','10000000-0000-4000-8000-'||lpad(n::text,12,'0'))
$$;
create function private.ovd591_retention_call(operation text) returns jsonb language plpgsql as $$
declare v jsonb; k text;
begin
 select kind,input into k,v from private.ovd591_retention_inputs where name=operation;
 case k when 'claim' then v:=public.api_prepare_capability_claim(v);
 when 'completion' then v:=public.api_prepare_capability_completion(v);
 when 'attention' then v:=public.api_prepare_capability_attention(v);
 else raise exception using errcode='22023',message='Unknown fixed operation.'; end case;
 return jsonb_build_object('result',v,'sqlstate',null);
exception when others then return jsonb_build_object('result',null,'sqlstate',SQLSTATE);
end $$;
revoke all on function private.ovd591_retention_claim(integer,integer) from public,anon,authenticated,service_role;
revoke all on function private.ovd591_retention_call(text) from public,anon,authenticated,service_role;
create function pg_temp.await_retention_overlap(expected integer[],blocker integer) returns jsonb language plpgsql as $$
declare receipt jsonb;
begin
 for i in 1..150 loop
  perform pg_stat_clear_snapshot();
  select jsonb_agg(jsonb_build_object('pid',pid,'blockers',pg_blocking_pids(pid),
   'waitEvent',wait_event,'observedAt',clock_timestamp()) order by pid) into receipt
  from pg_stat_activity where pid=any(expected) and wait_event_type='Lock'
   and blocker=any(pg_blocking_pids(pid));
  if coalesce(jsonb_array_length(receipt),0)=cardinality(expected) then return receipt; end if;
  perform pg_sleep(0.02);
 end loop;
 raise exception 'Expected exact backend overlap was not observed.';
end $$;
